(() => {
 'use strict';
 const parts = [
  {id:'neck-pickup',title:'Neck pickup',type:'Signal source',group:'neck',box:[28,300,475,185],pin:[55,320],description:'The neck humbucker feeds the neck volume control, shown in the right-hand column of this diagram.',specs:[['Construction','Humbucker'],['Leads','4 conductor + shield']],notes:'Black is the hot lead. Green and bare go to ground. Red and white are joined and insulated for the series connection.'},
  {id:'bridge-pickup',title:'Bridge pickup',type:'Signal source',group:'bridge',box:[28,573,475,182],pin:[55,594],description:'The bridge humbucker feeds the bridge volume control, shown in the left-hand column of this diagram.',specs:[['Construction','Humbucker'],['Control column','Left on diagram']],notes:'Follow the black hot lead to the bridge volume input. The green and bare leads terminate at ground.'},
  {id:'neck-volume',title:'Neck volume',type:'Volume control',group:'neck',ground:true,box:[991,761,166,221],pin:[1145,786],description:'Sets the neck pickup level. Its output continues to the three-way selector, while the modern tone circuit branches from its input.',specs:[['Resistance','500kΩ'],['Taper','Audio'],['Make on sheet','CTS']],notes:'The supplied sheet connects the tone capacitor to volume lug 1 (pickup input). The centre wiper carries the variable output to the selector.'},
  {id:'bridge-volume',title:'Bridge volume',type:'Volume control',group:'bridge',ground:true,box:[649,761,160,221],pin:[793,786],description:'Sets the bridge pickup level before the signal reaches the three-way selector.',specs:[['Resistance','500kΩ'],['Taper','Audio'],['Make on sheet','CTS']],notes:'The bridge hot lead and its tone capacitor meet at the volume input. Follow the centre wiper wire to the selector.'},
  {id:'neck-cap',title:'Neck tone capacitor',type:'Tone circuit',group:'neck',box:[1020,1028,69,109],pin:[1093,1047],description:'Works with the neck tone pot to reduce high frequencies as the tone control is turned down.',specs:[['Capacitance','0.022µF / 22nF'],['Series on sheet','Orange Drop'],['Rating on sheet','400V']],notes:'Modern connection shown: neck volume lug 1 to neck tone lug 2. The capacitor is part of a branch to ground, not a series connection in the main output path.'},
  {id:'bridge-cap',title:'Bridge tone capacitor',type:'Tone circuit',group:'bridge',box:[677,1028,64,109],pin:[750,1047],description:'Works with the bridge tone pot to control the amount of high-frequency roll-off.',specs:[['Capacitance','0.022µF / 22nF'],['Series on sheet','Orange Drop'],['Rating on sheet','400V']],notes:'Modern connection shown: bridge volume lug 1 to bridge tone lug 2. Use the sheet’s rear-view orientation to identify the terminals.'},
  {id:'neck-tone',title:'Neck tone',type:'Tone control',group:'neck',ground:true,box:[995,1170,160,223],pin:[1142,1257],description:'Varies the neck tone circuit’s path to ground. Turning the tone down increases the removal of high frequencies through the capacitor.',specs:[['Resistance','500kΩ'],['Taper','Audio'],['Make on sheet','CTS']],notes:'The capacitor meets tone lug 2, the centre terminal. The drawing also shows the grounded outer terminal and shared pot-case ground.'},
  {id:'bridge-tone',title:'Bridge tone',type:'Tone control',group:'bridge',ground:true,box:[649,1170,161,223],pin:[796,1257],description:'Controls the bridge pickup’s tone circuit independently of the neck tone setting.',specs:[['Resistance','500kΩ'],['Taper','Audio'],['Make on sheet','CTS']],notes:'Follow the capacitor to the centre tone terminal. The grounded outer terminal and pot case form part of the shared ground network.'},
  {id:'selector',title:'Three-way toggle',type:'Pickup selection',group:'shared',ground:true,box:[845,534,119,224],pin:[969,555],description:'Selects the neck pickup, bridge pickup or both together. The selected signal is sent to the output jack.',specs:[['Positions','Neck / both / bridge'],['Inputs','Two volume outputs']],notes:'The two volume outputs feed the pickup contacts. The common output feeds the jack tip. The switch frame has a separate ground connection.'},
  {id:'jack',title:'Output jack',type:'Signal output',group:'shared',ground:true,box:[169,1025,225,184],pin:[395,1080],description:'Connects the guitar circuit to your instrument cable. The tip carries the hot output and the sleeve connects to ground.',specs:[['Signal contact','Tip'],['Ground contact','Sleeve'],['Make on sheet','Switchcraft®']],notes:'Follow the selector output to the tip terminal. The other terminal is the ground sleeve. Identify these electrically if the jack’s physical layout differs.'},
  {id:'series',title:'Humbucker series links',type:'Joined & insulated',group:'shared',box:[679,505,83,121],pin:[762,526],description:'Each pickup’s red and white wires are joined to connect its two coils in series. These joints are insulated from the rest of the circuit.',specs:[['Wires on sheet','Red + white'],['Connection','One joint per pickup']],notes:'Keep each pickup’s series joint separate from the other pickup and from ground. This supplied diagram does not include coil splitting.'},
  {id:'ground',title:'Shared ground network',type:'Common reference',group:'ground',ground:true,box:[614,1290,527,139],pin:[915,1402],description:'The pot cases, pickup grounds, switch ground and output sleeve share a common electrical ground.',specs:[['Jack contact','Sleeve'],['Pickup leads','Green + bare']],notes:'Dashed lines on the sheet identify the pot-case ground links. The separate ground symbols refer to the same common ground; they are not separate isolated circuits.'}
 ];
 const steps=[
  {label:'Pickups',title:'Start at the pickups.',text:'Each humbucker has a hot output, a ground connection and a joined series pair. Neck controls sit on the right of this drawing; bridge controls sit on the left.',part:'neck-pickup',focus:'all'},
  {label:'Series links',title:'Join the coils in series.',text:'For the wire colours shown, each pickup’s red and white wires are soldered together and insulated. The two pickups keep separate series joints.',part:'series',focus:'all'},
  {label:'Volume',title:'Follow the hot lead to volume.',text:'The black pickup lead reaches the input of its volume pot. The centre wiper sends the adjustable signal onwards to the selector.',part:'neck-volume',focus:'neck'},
  {label:'Tone',title:'Explore the modern tone branch.',text:'The capacitor connects the volume input (lug 1 on this sheet) to the tone pot’s centre terminal (lug 2). This branch lets the tone control reduce high frequencies.',part:'neck-cap',focus:'neck'},
  {label:'Selector',title:'Choose the pickup circuit.',text:'The three-way toggle receives the two volume outputs and selects neck, bridge or both. Use Circuit focus above to inspect the components of either pickup channel.',part:'selector',focus:'all'},
  {label:'Output',title:'Take the signal to the jack.',text:'The selector’s common output goes to the jack tip. The sleeve is ground. These are two separate electrical connections.',part:'jack',focus:'all'},
  {label:'Grounds',title:'Bring the grounds together.',text:'Check the common ground connections shown for the pot cases, pickup leads, switch and jack sleeve. The ground symbols all refer to the same network.',part:'ground',focus:'ground'}
 ];
 const $=s=>document.querySelector(s), all=s=>[...document.querySelectorAll(s)];
 let selected=0,focus='all',step=0,zoom=1,fitWidth=480;
 const viewer=$('#viewer'),sheet=$('#sheet'),select=$('#component-select');
 const focusCopy={all:'Full diagram. Both pickup circuits and shared connections are visible.',neck:'Neck circuit: pickup → neck volume → selector → jack. Its capacitor and tone control form the tone branch.',bridge:'Bridge circuit: pickup → bridge volume → selector → jack. Its capacitor and tone control form the tone branch.',ground:'Ground focus: pot cases, pickup ground network, switch and jack sleeve. Highlights identify components, not individual solder points.'};
 parts.forEach((p,i)=>{
  const option=document.createElement('option');option.value=p.id;option.textContent=`${String(i+1).padStart(2,'0')} · ${p.title}`;select.append(option);
  const pin=document.createElement('button');pin.type='button';pin.className='hotspot';pin.textContent=i+1;pin.title=p.title;pin.setAttribute('aria-label',`Inspect ${p.title}`);pin.style.left=`${p.pin[0]/1376*100}%`;pin.style.top=`${p.pin[1]/1779*100}%`;pin.addEventListener('click',()=>{choose(i,false);if(window.innerWidth<=760) $('.inspector').scrollIntoView({behavior:'auto',block:'start'});});$('#hotspots').append(pin);
 });
 function relevant(p){return focus==='all'||(focus==='ground'?p.ground:p.group===focus||['selector','jack'].includes(p.id));}
 function highlight(){
  const group=$('#highlight-shapes');group.replaceChildren();
  parts.forEach((p,i)=>{const active=relevant(p);const pin=all('.hotspot')[i];pin.classList.toggle('muted',!active);pin.setAttribute('aria-pressed',String(i===selected));if(i===selected||(focus!=='all'&&active)){const rect=document.createElementNS('http://www.w3.org/2000/svg','rect');['x','y','width','height'].forEach((attr,j)=>rect.setAttribute(attr,p.box[j]));if(i===selected)rect.setAttribute('class','selected');group.append(rect);}});
 }
 function locate(p){const x=sheet.offsetLeft+p.box[0]/1376*sheet.clientWidth+p.box[2]/1376*sheet.clientWidth/2;const y=sheet.offsetTop+p.box[1]/1779*sheet.clientHeight+p.box[3]/1779*sheet.clientHeight/2;viewer.scrollTo({left:Math.max(0,x-viewer.clientWidth/2),top:Math.max(0,y-viewer.clientHeight/2),behavior:'auto'});}
 function choose(i,centre=true){selected=(i+parts.length)%parts.length;const p=parts[selected];select.value=p.id;$('#component-count').textContent=`${String(selected+1).padStart(2,'0')} / ${parts.length}`;$('#part-type').textContent=p.type;$('#part-title').textContent=p.title;$('#part-description').textContent=p.description;$('#part-notes').textContent=p.notes;$('#part-specs').replaceChildren();p.specs.forEach(([key,val])=>{const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=key;dd.textContent=val;row.append(dt,dd);$('#part-specs').append(row);});highlight();if(centre)locate(p);}
 function setFocus(value){focus=value;all('[data-focus]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.focus===value)));$('#focus-description').textContent=focusCopy[value];highlight();}
 all('[data-focus]').forEach(b=>b.addEventListener('click',()=>{setFocus(b.dataset.focus);if(focus==='neck')choose(0);if(focus==='bridge')choose(1);if(focus==='ground')choose(11);}));
 select.addEventListener('change',()=>choose(parts.findIndex(p=>p.id===select.value)));
 $('#previous-part').addEventListener('click',()=>choose(selected-1));$('#next-part').addEventListener('click',()=>choose(selected+1));
 function sizeSheet(){const style=getComputedStyle(viewer),padding=parseFloat(style.paddingLeft)+parseFloat(style.paddingRight);fitWidth=Math.max(150,Math.min(viewer.clientWidth-padding,(viewer.clientHeight-padding)*1584/2048));sheet.style.width=`${Math.round(fitWidth*zoom)}px`;$('#zoom-value').textContent=`${Math.round(zoom*100)}%`;$('#zoom-out').disabled=zoom<=1;$('#zoom-in').disabled=zoom>=3;}
 function setZoom(value){zoom=Math.max(1,Math.min(3,value));sizeSheet();if(zoom===1)viewer.scrollTo(0,0);else locate(parts[selected]);}
 $('#zoom-in').addEventListener('click',()=>setZoom(zoom+.25));$('#zoom-out').addEventListener('click',()=>setZoom(zoom-.25));$('#fit').addEventListener('click',()=>setZoom(1));
 $('#show-hotspots').addEventListener('change',e=>{$('#hotspots').hidden=!e.target.checked;});
 $('#print-diagram').addEventListener('click',()=>window.print());
 steps.forEach((s,i)=>{const b=document.createElement('button');b.textContent=`${i+1}. ${s.label}`;b.setAttribute('aria-pressed',String(i===0));b.addEventListener('click',()=>setStep(i));$('.step-buttons').append(b);});
 function setStep(i,move=true){step=i;const s=steps[i];$('#step-count').textContent=`Step ${i+1} of ${steps.length}`;$('#step-title').textContent=s.title;$('#step-text').textContent=s.text;$('#next-step').textContent=i===steps.length-1?'Start again ↺':'Next step →';all('.step-buttons button').forEach((b,j)=>b.setAttribute('aria-pressed',String(i===j)));if(move){setFocus(s.focus);choose(parts.findIndex(p=>p.id===s.part));}}
 $('#next-step').addEventListener('click',()=>setStep((step+1)%steps.length));
 function updateChecks(){$('#check-status').textContent=`${all('#checklist input:checked').length} of 4 checked`;}
 all('#checklist input').forEach(i=>i.addEventListener('change',updateChecks));$('#reset-checklist').addEventListener('click',()=>{all('#checklist input').forEach(i=>i.checked=false);updateChecks();});
 window.addEventListener('resize',sizeSheet);sheet.querySelector('img').addEventListener('load',sizeSheet);
 sizeSheet();choose(0,false);setStep(0,false);
})();
